@orders_bp.route("/export", methods=["GET"])
@require_role("manager")
def export_orders():
    """Export orders filtered by the X-Report-Filter header."""
    status_filter = request.headers.get("X-Report-Filter", "shipped")
    conn = get_engine().raw_connection()
    try:
        cursor = conn.cursor()
        cursor.execute(
            "SELECT id, user_id, status, total FROM orders WHERE status = ?",
            (status_filter,),
        )
        rows = cursor.fetchall()
    finally:
        conn.close()
    return jsonify([list(r) for r in rows])

def require_role(minimum_role: str):
    """Require at least the given role (user < manager < admin)."""

    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            user = get_current_user()
            if user is None:
                return jsonify({"error": "authentication required"}), 401
            if ROLE_RANK.get(user.role, 0) < ROLE_RANK.get(minimum_role, 99):
                return jsonify({"error": "insufficient role"}), 403
            g.current_user = user
            return fn(*args, **kwargs)

        return wrapper

    return decorator
